def _sets(o, h, l, c, eps):
    """Membership of the Goo-Chen-Chang one-day marubozu sets.

    Returns (bullish, bearish). eps is the equality tolerance in price units.
    """
    bull = False
    bear = False
    if c > o:
        # closing white marubozu: no upper shadow, a real lower one
        if abs(h - c) <= eps and (o - l) > eps:
            bull = True
        # opening white marubozu: no lower shadow, a real upper one
        elif abs(o - l) <= eps and (h - c) > eps:
            bull = True
    elif c < o:
        # closing black marubozu: no lower shadow, a real upper one
        if abs(c - l) <= eps and (h - o) > eps:
            bear = True
        # opening black marubozu: no upper shadow, a real lower one
        elif abs(o - h) <= eps and (c - l) > eps:
            bear = True
    return bull, bear


def family_init(ctx):
    bars = ctx.bars
    n = len(bars)
    f = float(ctx.p.eps_frac)
    bull = [False] * n
    bear = [False] * n
    for j in range(n):
        b = bars[j]
        o = float(b["o"]); h = float(b["h"]); l = float(b["l"]); c = float(b["c"])
        rng = h - l
        if rng <= 0:
            continue
        bu, be = _sets(o, h, l, c, f * rng)
        bull[j] = bu
        bear[j] = be
    ctx.bull = ctx.series(bull, "bullish_set_B")
    ctx.bear = ctx.series(bear, "bearish_set_S")
    ctx.e = ctx.indicator("ema", period=int(ctx.p.ema_n))


def signal(ctx, i):
    e = ctx.e[i]
    if e is None:
        return 0
    if ctx.bull[i] and ctx.c[i] > e:
        return 1
    # mode 0 = long only (flat on S); mode 1 = always in (reverse on S)
    if int(ctx.p.mode) == 1 and ctx.bear[i] and ctx.c[i] < e:
        return -1
    return 0


def exit_signal(ctx, i):
    """The whole idea: no clock, no level -- the opposing set ends the trade."""
    if not ctx.positions:
        return False
    if ctx.positions[0]["side"] == "long":
        return bool(ctx.bear[i])
    return bool(ctx.bull[i])
